#include <bits/stdc++.h>
using namespace std;
#define int long long
int32_t main() {
	int t;
	cin>>t;
	while(t--)
	{
	    int n;
	    cin>>n;
	    n=3*n;
	    vector<int> temp(n);
	    int base=0;
	    for(int i=0;i<n;i++)
	    {
	        cin>>temp[i];
	        base=base+3*temp[i];
	    }
	    sort(temp.begin(),temp.end());
	    reverse(temp.begin(),temp.end());
	    vector<int> v(n+1);
	    for(int i=1;i<=n;i++)
	    {
	        v[i]=temp[i-1];
	    }
	    for(int i=1;i<=n;i++)
	    {
	        v[i]+=v[i-1];
	    }
	    int ans=0;
	    for(int i=0;i<=n/3;i++)
	    {
	        int delta=v[i]*3 -3*(v[n]-v[n-2*i]);
	        //cout<<delta<<endl;
	        if(delta < 0)
	        {
	            break;
	        }
	        int l=0,r=n/3-i;
	        while(l<r)
	        {
	            int mid=(l+r+1)/2;
	            int delta2=v[i+2*mid]-v[i+2*mid-2]-3*(v[n-2*i-mid+1]-v[n-2*i-mid]);
	            if(delta2>0)
	            {
	                l=mid;
	            }
	            else
	            {
	                r=mid-1;
	            }
	        }
	        delta-=3*(v[n-2*i]-v[n-2*i-l]);
	        delta+=v[i+2*l]-v[i];
	        //cout<<delta<<endl;
	        ans=max(ans,base+delta);
	    }
	    cout<<ans<<'\n';
	}
}
